import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';

void main()=>runApp(MaterialApp(home: App(), debugShowCheckedModeBanner: false));

class App extends StatefulWidget{ @override State<App> createState()=>_S();}
class _S extends State<App>{
  List<Map<String,dynamic>> props=[
    {'title':'Modern Apartment Davao','loc':'Davao','price':15000,'cat':'House Rent','owner':'Anna','net':'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800','img':null},
    {'title':'Airbnb Makati','loc':'Makati','price':3000,'cat':'Airbnb','owner':'Mika','net':'https://images.unsplash.com/photo-1560448204-603b3fc33ddc?w=800','img':null},
  ];
  bool reg=false; String gt='019812345678'; String gc='09123456789';
  @override Widget build(BuildContext c){
    return Scaffold(
      appBar: AppBar(title: Text('Pinas Paupa 🇵🇭'), backgroundColor: Color(0xFF2E7D32)),
      body: ListView(children: [
        Container(margin: EdgeInsets.all(15), padding: EdgeInsets.all(12), decoration: BoxDecoration(color: reg?Colors.green.shade100:Colors.orange.shade100, borderRadius: BorderRadius.circular(12)), child: Row(children: [Icon(reg?Icons.verified:Icons.app_registration), SizedBox(width:10), Expanded(child: Text(reg?'REGISTERED AUTO $gt':'Wala pa ka naka-register!', style: TextStyle(fontWeight: FontWeight.bold))), ElevatedButton(onPressed: ()=>setState(()=>reg=true), child: Text('REGISTER'))])),
        GridView.count(crossAxisCount:2, shrinkWrap:true, physics:NeverScrollableScrollPhysics(), childAspectRatio:2.5, padding:EdgeInsets.all(10), children:[
          _btn('Airbnb',Icons.home,(){_open('Airbnb');}), _btn('House Rent',Icons.home_work,(){_open('House Rent');}),
          _btn('House Sale',Icons.house,(){_open('House Sale');}), _btn('Lot Rent',Icons.terrain,(){_open('Lot Rent');}),
          _btn('Lot Sale',Icons.landscape,(){_open('Lot Sale');}), _btn('Rent Car',Icons.car_rental,(){_open('Rent Car');}),
          _btn('Food',Icons.fastfood,(){_open('Food');}), _btn('Services',Icons.build,(){_open('Services');}),
        ]),
        ...props.map((p){int com=(p['price']*0.15).toInt(); Widget im=p['img']!=null?Image.file(p['img'],height:180,width:double.infinity,fit:BoxFit.cover):Image.network(p['net'],height:180,width:double.infinity,fit:BoxFit.cover); return Card(margin:EdgeInsets.all(10), child:Column(children:[ClipRRect(borderRadius:BorderRadius.vertical(top:Radius.circular(10)), child:im), ListTile(title:Text(p['title']), subtitle:Text('${p['loc']} ₱${p['price']} Kita ₱$com')), Row(children:[Expanded(child:OutlinedButton.icon(icon:Icon(Icons.chat), label:Text('Chat'), onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(owner:p['owner'], title:p['title']))))), Expanded(child:ElevatedButton(onPressed:()=>showModalBottomSheet(context:c, builder:(_)=>Pay(price:p['price'], com:com, gt:gt, gc:gc)), child:Text('Book')))]),])));}).toList(),
      ]),
      floatingActionButton: FloatingActionButton.extended(icon:Icon(Icons.add_a_photo), label:Text('MAG POST + PICTURE'), backgroundColor:Colors.orange, onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Post(onAdd:(m)=>setState(()=>props.insert(0,m)))))),
    );
  }
  Widget _btn(String t,IconData ic, VoidCallback f){return Card(child: InkWell(onTap:f, child: Center(child: Column(mainAxisSize:MainAxisSize.min, children:[Icon(ic), Text(t)]))));}
  void _open(String cat){Navigator.push(context, MaterialPageRoute(builder:(_)=>CatPage(cat:cat, props:props, gt:gt, gc:gc)));}
}

class CatPage extends StatelessWidget{final String cat; final List props; final String gt,gc; CatPage({required this.cat, required this.props, required this.gt, required this.gc}); @override Widget build(BuildContext c){var f=props.where((e)=>e['cat']==cat).toList(); return Scaffold(appBar:AppBar(title:Text(cat), backgroundColor:Color(0xFF2E7D32)), body:ListView.builder(itemCount:f.length, itemBuilder:(c,i){var p=f[i]; Widget im=p['img']!=null?Image.file(p['img'],height:160,width:double.infinity,fit:BoxFit.cover):Image.network(p['net'],height:160,width:double.infinity,fit:BoxFit.cover); return Card(margin:EdgeInsets.all(10), child:Column(children:[im, ListTile(title:Text(p['title']), subtitle:Text('₱${p['price']}')), Row(children:[Expanded(child:OutlinedButton(icon:Icon(Icons.chat), label:Text('Chat'), onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(owner:p['owner'], title:p['title']))))), Expanded(child:ElevatedButton(onPressed:()=>showModalBottomSheet(context:c, builder:(_)=>Pay(price:p['price'], com:(p['price']*0.15).toInt(), gt:gt, gc:gc)), child:Text('Book')))])]));}));}}

class Chat extends StatefulWidget{final String owner,title; Chat({required this.owner, required this.title}); @override State<Chat> createState()=>_ChatState();}
class _ChatState extends State<Chat>{List<String> msgs=[]; var ctrl=TextEditingController(); @override void initState(){super.initState(); msgs=['Hello ${widget.owner}, available pa?', 'Yes boss available!'];} @override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text('Chat ${widget.owner}'), backgroundColor:Color(0xFF2E7D32)), body:Column(children:[Expanded(child:ListView.builder(itemCount:msgs.length, itemBuilder:(c,i)=>Container(margin:EdgeInsets.all(8), padding:EdgeInsets.all(12), decoration:BoxDecoration(color:i%2==0?Color(0xFF2E7D32):Colors.grey.shade200, borderRadius:BorderRadius.circular(12)), child:Text(msgs[i], style:TextStyle(color:i%2==0?Colors.white:Colors.black))))), Padding(padding:EdgeInsets.all(10), child:Row(children:[Expanded(child:TextField(controller:ctrl, decoration:InputDecoration(hintText:'Maka-chat tinuod! Type...', border:OutlineInputBorder()))), IconButton(icon:Icon(Icons.send), onPressed:(){if(ctrl.text.isNotEmpty){setState(()=>msgs.add(ctrl.text)); ctrl.clear(); Future.delayed(Duration(seconds:1), ()=>setState(()=>msgs.add('Copy boss! Reply ko - GCash/GoTyme ta')));}})]))])));}}

class Post extends StatefulWidget{final Function(Map<String,dynamic>) onAdd; Post({required this.onAdd}); @override State<Post> createState()=>_PostState();}
class _PostState extends State<Post>{var t=TextEditingController(); var p=TextEditingController(); File? img; final pk=ImagePicker(); Future<void> getImg(ImageSource s)async{var x=await pk.pickImage(source:s); if(x!=null)setState(()=>img=File(x.path));} @override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text('POST + PICTURE TINUOD!')), body:Padding(padding:EdgeInsets.all(15), child:ListView(children:[InkWell(onTap:()=>getImg(ImageSource.gallery), child:Container(height:200, decoration:BoxDecoration(color:Colors.grey.shade200, borderRadius:BorderRadius.circular(12)), child:img!=null?Image.file(img!, fit:BoxFit.cover):Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(Icons.add_a_photo, size:50), Text('CLICK PARA PILI PICTURE SA GALLERY!', style:TextStyle(fontWeight:FontWeight.bold))]))), Row(children:[Expanded(child:ElevatedButton.icon(icon:Icon(Icons.photo), label:Text('Gallery'), onPressed:()=>getImg(ImageSource.gallery))), SizedBox(width:8), Expanded(child:ElevatedButton.icon(icon:Icon(Icons.camera), label:Text('Camera'), onPressed:()=>getImg(ImageSource.camera)))]), TextField(controller:t, decoration:InputDecoration(labelText:'Title')), TextField(controller:p, decoration:InputDecoration(labelText:'Price'), keyboardType:TextInputType.number), SizedBox(height:10), ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), onPressed:(){if(t.text.isEmpty||img==null){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Butangi Title + Picture!'))); return;} widget.onAdd({'title':t.text, 'price':int.tryParse(p.text)??15000, 'loc':'Davao', 'cat':'House Rent', 'owner':'Ikaw', 'img':img, 'net':''}); Navigator.pop(c);}, child:Text('I-POST NA!'))])));}}

class Pay extends StatelessWidget{final int price,com; final String gt,gc; Pay({required this.price, required this.com, required this.gt, required this.gc}); @override Widget build(BuildContext c){return Container(padding:EdgeInsets.all(20), child:Column(children:[Text('Bayad ₱$price Commission ₱$com AUTO $gt', style:TextStyle(fontWeight:FontWeight.bold)), Wrap(children:['GCash','GoTyme','BPI','BDO','Metrobank'].map((e)=>Chip(label:Text(e))).toList()), ElevatedButton(onPressed:(){Navigator.pop(c); ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('✅ Bayad na! ₱$com AUTO sa $gt')));}, child:Text('BAYARAN ₱$price'))]));}}
